package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"strconv"
	"strings"
	"time"

	_ "github.com/mattn/go-sqlite3"
)

var db *sql.DB
var apiSecretKey = []byte("k8s-internal-signing-key-2024-prod")

const proxySignatureMaxAge = 5 * time.Minute

type RateLimiter struct {
	window    map[string][]time.Time
	maxPerSec int
}

func NewRateLimiter(max int) *RateLimiter {
	return &RateLimiter{window: make(map[string][]time.Time), maxPerSec: max}
}

func (rl *RateLimiter) Allow(ip string) bool {
	now := time.Now()
	cutoff := now.Add(-1 * time.Second)
	var recent []time.Time
	for _, t := range rl.window[ip] {
		if t.After(cutoff) {
			recent = append(recent, t)
		}
	}
	rl.window[ip] = append(recent, now)
	return len(recent) < rl.maxPerSec
}

func computeTokenMAC(userID, sessionNonce string) string {
	mac := hmac.New(sha256.New, apiSecretKey)
	mac.Write([]byte(userID + ":" + sessionNonce))
	return hex.EncodeToString(mac.Sum(nil))
}

func validateProxySignature(r *http.Request) bool {
	sig := r.Header.Get("X-Proxy-Signature")
	timestamp := r.Header.Get("X-Proxy-Timestamp")
	if sig == "" || timestamp == "" {
		return false
	}

	// Reject stale/future timestamps to prevent signature replay.
	tsUnix, err := strconv.ParseInt(timestamp, 10, 64)
	if err != nil {
		return false
	}
	ts := time.Unix(tsUnix, 0)
	now := time.Now()
	if now.Sub(ts) > proxySignatureMaxAge || ts.Sub(now) > proxySignatureMaxAge {
		return false
	}

	expected := computeProxyMAC(r.URL.Path, timestamp)
	return hmac.Equal([]byte(sig), []byte(expected))
}

func computeProxyMAC(path, timestamp string) string {
	mac := hmac.New(sha256.New, apiSecretKey)
	mac.Write([]byte(path + ":" + timestamp))
	return hex.EncodeToString(mac.Sum(nil))
}

func extractClientIP(r *http.Request) string {
	if xff := r.Header.Get("X-Forwarded-For"); xff != "" {
		parts := strings.Split(xff, ",")
		return strings.TrimSpace(parts[0])
	}
	return r.RemoteAddr
}

func authenticateAPIToken(r *http.Request) (string, bool) {
	authHeader := r.Header.Get("Authorization")
	if !strings.HasPrefix(authHeader, "Bearer ") {
		return "", false
	}
	token := strings.TrimPrefix(authHeader, "Bearer ")
	parts := strings.SplitN(token, ".", 3)
	if len(parts) != 3 {
		return "", false
	}
	userID := parts[0]
	nonce := parts[1]
	providedMAC := parts[2]

	expectedMAC := computeTokenMAC(userID, nonce)

	// Verify the token integrity using constant-time comparison
	if !hmac.Equal([]byte(expectedMAC), []byte(providedMAC)) {
		return "", false
	}

	// Check if session is still valid in database
	var active bool
	err := db.QueryRow("SELECT active FROM sessions WHERE user_id = ? AND nonce = ?", userID, nonce).Scan(&active)
	if err != nil || !active {
		return "", false
	}

	return userID, true
}

func handleUserProfile(w http.ResponseWriter, r *http.Request) {
	if !validateProxySignature(r) {
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	userID, authenticated := authenticateAPIToken(r)
	if !authenticated {
		http.Error(w, "Unauthorized", http.StatusUnauthorized)
		return
	}

	var displayName, email string
	err := db.QueryRow("SELECT display_name, email FROM users WHERE id = ?", userID).Scan(&displayName, &email)
	if err != nil {
		http.Error(w, "Not Found", http.StatusNotFound)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"user_id":%q,"display_name":%q,"email":%q}`, userID, displayName, email)
}

func main() {
	var err error
	db, err = sql.Open("sqlite3", "./mobile_backend.db")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	db.Exec(`CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, display_name TEXT, email TEXT)`)
	db.Exec(`CREATE TABLE IF NOT EXISTS sessions (user_id TEXT, nonce TEXT, active BOOLEAN, PRIMARY KEY(user_id, nonce))`)

	limiter := NewRateLimiter(100)

	http.HandleFunc("/api/v1/profile", func(w http.ResponseWriter, r *http.Request) {
		clientIP := extractClientIP(r)
		if !limiter.Allow(clientIP) {
			http.Error(w, "Rate Limited", http.StatusTooManyRequests)
			return
		}
		handleUserProfile(w, r)
	})

	log.Println("Mobile backend API listening on :8081")
	log.Fatal(http.ListenAndServe(":8081", nil))
}
